(x, y, t) => {
  const cx = 240, cy = 120;
  const wx = Math.sin(x*0.02+t*0.3)*15 + Math.cos(y*0.015-t*0.2)*10 + Math.sin((x+y)*0.01+t*0.5)*8;
  const wy = Math.cos(y*0.02-t*0.25)*15 + Math.sin(x*0.018+t*0.35)*10 + Math.cos((x-y)*0.012-t*0.4)*8;
  const sx = x + wx, sy = y + wy;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9],
    [80+Math.sin(t*0.45+3)*70, 40+Math.cos(t*0.65)*50, 0.11, 2.1],
    [400+Math.cos(t*0.55+2)*60, 220+Math.sin(t*0.75+1)*40, 0.085, 1.8]
  ];
  let aS = 0, iS = 0, glow = 0;
  for (const [sX, sY, f, sp] of src) {
    const d = Math.sqrt((sx-sX)**2 + (sy-sY)**2);
    aS += Math.sin(d*f - t*sp);
    iS += Math.sin(d*f*0.7 + t*sp*0.6 + 1.5);
    glow += Math.exp(-d*0.012)*0.15;
  }
  const act = aS/8, inh = iS/8;
  const src2 = [
    [200+Math.sin(t*1.2)*60, 100+Math.cos(t*0.9)*40, 0.18, 3.0],
    [280+Math.cos(t*1.1)*50, 140+Math.sin(t*1.3)*30, 0.22, 2.7],
    [240+Math.sin(t*0.8+1)*80, 120+Math.cos(t+2)*60, 0.15, 3.3]
  ];
  let aS2 = 0;
  for (const [sX, sY, f, sp] of src2) {
    const d = Math.sqrt((sx-sX)**2 + (sy-sY)**2);
    aS2 += Math.sin(d*f - t*sp);
  }
  const detail = aS2/3*0.3;
  const bg = (Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1)+Math.sin(sx*0.02+sy*0.05-t*0.7))/3+Math.sin((sx+sy)*0.12+t*2.5)*0.15+Math.sin((sx-sy)*0.1-t*2)*0.15;
  const dist = Math.sqrt((sx-cx)**2+(sy-cy)**2), ang = Math.atan2(sy-cy, sx-cx);
  const spiral = (Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2)+Math.sin(dist*0.06-ang*2+t*0.8))*0.3;
  const cell = Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5+Math.sin(sx*0.08-t*0.3)*Math.cos(sy*0.12+t*0.2))*1.5)*0.25;
  const reaction = Math.tanh((act-inh*0.7+bg*0.3+spiral+detail)*2.2);
  const feedback = Math.sin(reaction*3+act*0.5-t*0.8)*0.15;
  const blend = reaction*0.6+cell*0.2+feedback*0.15+glow*0.05;
  const v = blend*0.5+0.5;
  const pal = [[5,12,52],[12,55,95],[18,110,120],[35,160,140],[180,195,80],[220,170,60],[215,110,65],[185,60,60],[130,35,70],[70,20,65],[30,15,55],[5,12,52]];
  const idx = v*(pal.length-1), i = Math.min(idx|0, pal.length-2), f = idx-i, sf = f*f*(3-2*f);
  const lum = 0.85+Math.sin(reaction*Math.PI)*0.15;
  const edge = Math.abs(reaction)>0.75?1.2:Math.abs(reaction)>0.5?1.05:0.95;
  const vig = 1-Math.pow(dist/300,2)*0.25;
  return [
    Math.min(255,(pal[i][0]+(pal[i+1][0]-pal[i][0])*sf)*lum*edge*vig)|0,
    Math.min(255,(pal[i][1]+(pal[i+1][1]-pal[i][1])*sf)*lum*edge*vig)|0,
    Math.min(255,(pal[i][2]+(pal[i+1][2]-pal[i][2])*sf)*lum*edge*vig)|0
  ];
}
